const ELEMENT_PROP_KEYS = new Set(["theme","round","call","fontWeight","shake","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  round: "ROUND 1",
  call: "SHIP!",
  fontWeight: 500,
  shake: 1,
  accent: "#3B5BFD",
  fontFamily: "Unbounded",
  scale: 1,
  delay: 0,
  speed: 1,
};

type RoundSlamElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RoundSlamBase>;

const RoundSlamInner = forwardRef<
  HTMLDivElement,
  RoundSlamElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<RoundSlam>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RoundSlamBase
          {...(componentProps as unknown as ComponentProps<typeof RoundSlamBase>)}
        />
      </div>
    </Sequence>
  );
});

export const RoundSlam = Interactive.withSchema({
  Component: RoundSlamInner,
  componentName: "<RoundSlam>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
